protected function isPartOfSchema($kind, $name, ?Endpoint $endpoint = NULL) {
  static $previous_calls;

  $endpoint_key = $endpoint ? $endpoint->getKey() : $this->getServer()->id();

  $state = $this->state;
  // This state is reset once a day via cron.
  $schema_parts = $state->get('search_api_solr.endpoint.schema_parts');

  if (
    !is_array($schema_parts) ||
    empty($schema_parts[$endpoint_key]) ||
    empty($schema_parts[$endpoint_key][$kind]) ||
    (!in_array($name, $schema_parts[$endpoint_key][$kind]) && !isset($previous_calls[$endpoint_key][$kind]))
  ) {
    $response = $this->getSolrConnector()
      ->coreRestGet('schema/' . strtolower($kind), $endpoint);
    if (empty($response[$kind])) {
      throw new SearchApiSolrException('Missing information about ' . $kind . ' in response to REST request.');
    }
    // Delete the old state.
    $schema_parts[$endpoint_key][$kind] = [];
    foreach ($response[$kind] as $row) {
      $schema_parts[$endpoint_key][$kind][] = $row['name'];
    }
    $state->set('search_api_solr.endpoint.schema_parts', $schema_parts);
    $previous_calls[$endpoint_key][$kind] = TRUE;
  }

  return in_array($name, $schema_parts[$endpoint_key][$kind]);

$version = $connector->getSolrVersion();
$info[] = [
  'label' => $this->t('Configured Solr Version'),
  'info' => $version,
  'status' => version_compare($version, '0.0.0', '>') ? 'ok' : 'error',
];

if ($ping_server || $ping) {
  $version = $connector->getSolrVersion(TRUE);
  $info[] = [
    'label' => $this->t('Detected Solr Version'),
    'info' => $version,
    'status' => 'ok',
  ];
  if (version_compare($connector->getSolrVersion(), '9.8.0', '>=')) {
    $this->messenger()
      ->addWarning($this->t('"lib" directives in solrconfig.xml are deprecated and will be removed in Solr 10.0. Ensure to load the required modules in your Solr 9.8 or higher server. One way is to set the SOLR_MODULES environment variable to include the modules required by Search API Solr per default: SOLR_MODULES="extraction,langid,ltr,analysis-extras".'));
  }

  try {
    $endpoints[0] = $connector->getEndpoint();
    $endpoints_queried = [];

    foreach ($this->getServer()->getIndexes() as $index) {
      $endpoints[$index->id()] = $this->getCollectionEndpoint($index);
    }

    /** @var \Solarium\Core\Client\Endpoint $endpoint */
    foreach ($endpoints as $index_id => $endpoint) {
      try {
        $key = $endpoint->getBaseUri();
      }
      catch (UnexpectedValueException $e) {
        if ($cloud && 0 === $index_id) {
          $info[] = [
            'label' => $this->t('Default Collection'),
            'info' => $this->t("Default collection isn't set. Ensure that the collections are properly set on the indexes in their advanced section of the Solr specific index options."),
            'status' => 'error',
          ];
        }
        else {
          $info[] = [
            'label' => $this->t('Additional information'),
            'info' => $this->t('Collection or core configuration for index %index is wrong or missing: %msg', [
              '%index' => $index_id,
              '%msg' => $e->getMessage(),
            ]),
            'status' => 'error',
          ];
        }
        continue;
      }

      if (!in_array($key, $endpoints_queried)) {
        $endpoints_queried[] = $key;
        if ($cloud) {
          $connector->setCollectionNameFromEndpoint($endpoint);
        }
        $data = $connector->getLuke();
        if (isset($data['index']['numDocs'])) {
          // Collect the stats.
          $stats_summary = $connector->getStatsSummary();

          if ($data['index']['numDocs'] !== -1) {
            $pending_msg = $stats_summary['@pending_docs'] ? $this->t('(@pending_docs sent but not yet processed)', $stats_summary) : '';
            $index_msg = $stats_summary['@index_size'] ? $this->t('(@index_size on disk)', $stats_summary) : '';
            $indexed_message = $this->t('@num items @pending @index_msg', [
              '@num' => $data['index']['numDocs'],
              '@pending' => $pending_msg,
              '@index_msg' => $index_msg,
            ]);
            $info[] = [
              'label' => $this->t('%key: Indexed', ['%key' => $key]),
              'info' => $indexed_message,
            ];

public function getStatsSummary() {
  $this->connect();
  $this->useTimeout();

  $summary = [
    '@pending_docs' => '',
    '@autocommit_time_seconds' => '',
    '@autocommit_time' => '',
    '@deletes_by_id' => '',
    '@deletes_by_query' => '',
    '@deletes_total' => '',
    '@schema_version' => '',
    '@core_name' => '',
    '@index_size' => '',
  ];

  $query = $this->solr->createPing();
  $query->setResponseWriter(Query::WT_JSON);
  $query->addParam('json.nl', 'map');
  $query->setHandler('admin/mbeans?stats=true');
  $stats = $this->execute($query)->getData();
  if (!empty($stats)) {
    $solr_version = $this->getSolrVersion(TRUE);
    $max_time = -1;
    if (version_compare($solr_version, '7.0', '>=')) {
      $update_handler_stats = $stats['solr-mbeans']['UPDATE']['updateHandler']['stats'];
      $summary['@pending_docs'] = (int) $update_handler_stats['UPDATE.updateHandler.docsPending'];
      if (isset($update_handler_stats['UPDATE.updateHandler.softAutoCommitMaxTime'])) {
        $max_time = (int) $update_handler_stats['UPDATE.updateHandler.softAutoCommitMaxTime'];
      }
      $summary['@deletes_by_id'] = (int) $update_handler_stats['UPDATE.updateHandler.deletesById'];
      $summary['@deletes_by_query'] = (int) $update_handler_stats['UPDATE.updateHandler.deletesByQuery'];
      $summary['@core_name'] = $stats['solr-mbeans']['CORE']['core']['stats']['CORE.coreName'] ?? $this->t('No information available.');
      $summary['@index_size'] = $stats['solr-mbeans']['CORE']['core']['stats']['INDEX.size'] ?? $this->t('No information available.');
    }
    else {
      $update_handler_stats = $stats['solr-mbeans']['UPDATEHANDLER']['updateHandler']['stats'];
      $summary['@pending_docs'] = (int) $update_handler_stats['docsPending'];
      $max_time = (int) $update_handler_stats['autocommit maxTime'];
      $summary['@deletes_by_id'] = (int) $update_handler_stats['deletesById'];
      $summary['@deletes_by_query'] = (int) $update_handler_stats['deletesByQuery'];
      $summary['@core_name'] = $stats['solr-mbeans']['CORE']['core']['stats']['coreName'] ?? $this->t('No information available.');
      if (version_compare($solr_version, '6.4', '>=')) {
        // @see https://issues.apache.org/jira/browse/SOLR-3990
        $summary['@index_size'] = $stats['solr-mbeans']['CORE']['core']['stats']['size'] ?? $this->t('No information available.');
      }
      else {
        $summary['@index_size'] = $stats['solr-mbeans']['QUERYHANDLER']['/replication']['stats']['indexSize'] ?? $this->t('No information available.');
      }
    }

    $summary['@autocommit_time_seconds'] = $max_time / 1000;
    $summary['@autocommit_time'] = $this->dateFormatter->formatInterval($max_time / 1000);
    $summary['@deletes_total'] = $summary['@deletes_by_id'] + $summary['@deletes_by_query'];
    $summary['@schema_version'] = $this->getSchemaVersionString(TRUE);
  }

protected function getAutocompleteTermSuggestions(ResultInterface $result, SuggestionFactory $suggestion_factory, $incomplete_key) {
  $suggestions = [];
  if ($result instanceof AutocompleteResult && ($terms_results = $result->getComponent(ComponentAwareQueryInterface::COMPONENT_TERMS))) {
    $autocomplete_terms = [];
    foreach ($terms_results as $fields) {
      foreach ($fields as $term => $count) {
        $autocomplete_terms[$term] = $count;
      }
    }

    foreach ($autocomplete_terms as $term => $count) {
      $suggestion_suffix = mb_substr($term, mb_strlen($incomplete_key));
      $suggestions[] = $suggestion_factory->createFromSuggestionSuffix($suggestion_suffix, $count);
    }
  }
  return $suggestions;
